const domainKnowledge={
"first-peoples":{part:"people",title:"First Peoples",teach:"Aboriginal and Torres Strait Islander peoples are Australia’s First Peoples. Their diverse cultures, languages and connections to Country continue today.",cue:"First Peoples → continuing cultures and connection to Country"},
"settlement":{part:"people",title:"Settlement and development",teach:"The First Fleet arrived from Great Britain in 1788. This marks British settlement and must not be confused with Federation in 1901.",cue:"1788 settlement ≠ 1901 Federation"},
"states":{part:"people",title:"States, territories and capitals",teach:"Australia has six states and two mainland territories. Canberra is the national capital.",cue:"Know every jurisdiction ↔ capital pair"},
"traditions":{part:"people",title:"Traditions and important days",teach:"Australia Day is 26 January and Anzac Day is 25 April. Ceremonies such as Welcome to Country and Acknowledgement of Country recognise First Peoples and connection to Country.",cue:"26 Jan Australia Day · 25 Apr Anzac Day"},
"flags":{part:"people",title:"Australia’s flags",teach:"The Australian National Flag, Australian Aboriginal Flag and Torres Strait Islander Flag are important recognised flags with distinct symbolism.",cue:"Know all three flags, not only the national flag"},
"symbols":{part:"people",title:"National symbols",teach:"Green and gold are the national colours, golden wattle is the national floral emblem, and Advance Australia Fair is the national anthem.",cue:"green + gold · golden wattle · Advance Australia Fair"},
"democracy":{part:"rights",title:"Parliamentary democracy",teach:"Australian citizens elect representatives to Parliament and can participate peacefully in public life.",cue:"citizens → elect representatives"},
"rule-law":{part:"rights",title:"Rule of law",teach:"Everyone is subject to Australian law. No person, organisation, official, cultural practice or religious rule is above it.",cue:"No one above Australian law"},
"peaceful-change":{part:"rights",title:"Peaceful democratic change",teach:"Political and social change should be pursued through peaceful, lawful democratic methods rather than violence.",cue:"disagree → participate peacefully"},
"speech":{part:"rights",title:"Freedom of speech",teach:"People may express ideas and opinions within Australian law while respecting the rights of others.",cue:"freedom operates within law"},
"association":{part:"rights",title:"Freedom of association",teach:"People may choose to join or leave lawful organisations and groups.",cue:"join or leave lawful groups"},
"religion":{part:"rights",title:"Freedom of religion",teach:"People may follow a religion or no religion. Australia has no official national religion and religious rules do not override Australian law.",cue:"belief is free · Australian law remains supreme"},
"equality-law":{part:"rights",title:"Equality under law",teach:"People are entitled to equal treatment under Australian law regardless of background.",cue:"same legal protection"},
"gender":{part:"rights",title:"Gender equality",teach:"Men and women have equal rights in Australia.",cue:"equal rights regardless of gender"},
"fair-go":{part:"rights",title:"Fair go",teach:"A fair go is associated with equality of opportunity, fairness and mutual respect.",cue:"fair opportunity, not guaranteed equal outcomes"},
"responsibilities":{part:"rights",title:"Responsibilities of citizenship",teach:"Responsibilities include obeying Australian laws, voting when required, serving on a jury when called and eligible, and defending Australia should the need arise.",cue:"law · vote · jury · defend"},
"privileges":{part:"rights",title:"Privileges of citizenship",teach:"Privileges include applying for an Australian passport and re-entering Australia freely, seeking election when eligible, applying for APS/ADF work, consular assistance overseas, and applying for eligible children born overseas to become citizens by descent.",cue:"passport · stand for office · consular help"},
"participation":{part:"rights",title:"Participation and taxation",teach:"Citizens are encouraged to participate in community life. Taxation helps fund government services and infrastructure.",cue:"participate + contribute"},
"say":{part:"government",title:"Voting and secret ballot",teach:"Eligible citizens enrol and vote. Voting is by secret ballot so an individual’s choice is private.",cue:"vote is compulsory when required; choice is secret"},
"aec":{part:"government",title:"Australian Electoral Commission",teach:"The Australian Electoral Commission administers federal elections and referendums and maintains the electoral roll.",cue:"AEC → elections · referendums · electoral roll"},
"federation":{part:"government",title:"Federation and Constitution",teach:"On 1 January 1901 the six colonies federated as the Commonwealth of Australia. The Constitution provides the framework for national government.",cue:"1901 → Commonwealth + Constitution"},
"referendum":{part:"government",title:"Referendums",teach:"The Australian Constitution can be changed through a referendum. Constitutional change requires the prescribed majority support, commonly described as a double majority.",cue:"Constitutional change → referendum"},
"powers":{part:"government",title:"Three powers",teach:"Legislative power makes laws, executive power puts them into action, and judicial power interprets and applies them.",cue:"MAKE → DO → JUDGE"},
"head-state":{part:"government",title:"Head of State and Governor-General",teach:"Australia is a constitutional monarchy. The King is Australia’s Head of State and the Governor-General represents the King at the Commonwealth level.",cue:"King → Head of State · Governor-General → representative"},
"parliament":{part:"government",title:"Australian Parliament",teach:"The Australian Parliament includes the House of Representatives and the Senate.",cue:"House + Senate"},
"leaders":{part:"government",title:"Political leaders",teach:"The Prime Minister leads the Australian Government; Premiers lead state governments; Chief Ministers lead territory governments; mayors lead many local councils.",cue:"PM · Premier · Chief Minister · Mayor"},
"levels":{part:"government",title:"Three levels",teach:"Federal government handles matters such as taxation, immigration, defence, trade, communications, social security and foreign affairs; states and territories handle services such as hospitals, schools, police, roads and public transport; local government handles services such as local roads, parks, rubbish, libraries, building permits and local environmental issues.",cue:"national · regional · local"},
"parties":{part:"government",title:"Parties and Opposition",teach:"Elected representatives may belong to political parties or be independents. The party or coalition with sufficient support forms government; other major parliamentary forces form the Opposition.",cue:"government vs Opposition"},
"ministers":{part:"government",title:"Ministers and Cabinet",teach:"Ministers are responsible for government portfolios. Senior ministers form Cabinet and make major government decisions.",cue:"portfolio → minister · senior ministers → Cabinet"},
"laws":{part:"government",title:"Making laws",teach:"A proposed law is a Bill. Parliament considers Bills and Royal Assent is part of the process by which a passed Bill becomes law.",cue:"Bill → Parliament → Royal Assent → law"},
"courts":{part:"government",title:"Courts and juries",teach:"Judges and magistrates decide legal cases. In some criminal trials, a jury of citizens decides whether the accused is guilty based on the evidence and law.",cue:"judge/magistrate + jury"},
"police":{part:"government",title:"Police and AFP",teach:"Police maintain peace and safety and enforce law. The Australian Federal Police handles federal policing responsibilities.",cue:"police enforce law · AFP federal role"},
"law-types":{part:"government",title:"Criminal, family violence and traffic law",teach:"Serious offences are governed by criminal law. Domestic and family violence is not accepted in Australia, and road users must obey traffic laws.",cue:"violence is unlawful · traffic laws apply"},
"freedom-dignity":{part:"values",title:"Freedom and dignity",teach:"Australian Values include respect for the freedom and dignity of every individual.",cue:"respect lawful freedom + dignity"},
"values-law":{part:"values",title:"Law and democracy",teach:"Australian Values include commitment to parliamentary democracy and the rule of law.",cue:"democracy + law"},
"values-freedoms":{part:"values",title:"Freedoms",teach:"Freedom of speech, religion and association are important values exercised within Australian law.",cue:"freedom within law"},
"values-equality":{part:"values",title:"Equality",teach:"Australian Values include equality under law and equality of opportunity, including equal rights for men and women.",cue:"equal law + equal opportunity"},
"mutual-respect":{part:"values",title:"Mutual respect and tolerance",teach:"People should respect lawful differences and treat others with tolerance and fairness.",cue:"fair go + mutual respect"},
"community":{part:"values",title:"Community contribution",teach:"Compassion, mateship, volunteering and contributing to the community are valued parts of Australian society.",cue:"help · contribute · volunteer"},
"english":{part:"values",title:"English language",teach:"English is Australia’s national language and is an important unifying element in Australian society.",cue:"English → national language"},
"safety":{part:"values",title:"Community safety and cyber abuse",teach:"Violence, threats and abuse are inconsistent with community safety. Cyber abuse can use technology to threaten, intimidate, harass or humiliate.",cue:"online harm still counts as abuse"},
"loyalty":{part:"values",title:"Loyalty and obligations",teach:"Australian citizens pledge loyalty to Australia and its people and must not undermine Australia’s interests and security. Australian law applies within Australia, and some Australian laws also apply to citizens overseas. Dual citizens may additionally have obligations under another country’s laws.",cue:"citizenship → loyalty + continuing obligations"}
};
const domainEnrichment={
"first-peoples":["Citizenship knowledge begins with recognising that Australia’s human story predates European settlement by many thousands of years.","A Welcome to Country is delivered by a Traditional Custodian; an Acknowledgement of Country can be offered by others.","Do not treat 1788 as the beginning of Australian human history.","FIRST PEOPLES → continuing cultures → Country"],
"settlement":["This domain separates British settlement from later constitutional nation-building.","1788 marks the First Fleet; 1901 marks Federation.","1788 and 1901 are not interchangeable milestones.","1788 SETTLEMENT ≠ 1901 FEDERATION"],
"states":["Geography questions test whether you can pair jurisdictions with capitals and distinguish the national capital.","South Australia → Adelaide; Western Australia → Perth; Australia → Canberra.","Sydney is Australia’s largest-city reference for many learners, but it is not the national capital.","JURISDICTION → CAPITAL"],
"traditions":["National days and ceremonies connect historical events with contemporary civic identity.","Anzac Day is 25 April; Australia Day is 26 January.","Do not swap the two dates or confuse Welcome to Country with Acknowledgement of Country.","25 APR → ANZAC · 26 JAN → AUSTRALIA DAY"],
"flags":["The three recognised flags represent different dimensions of Australia’s national and First Peoples identity.","The Aboriginal and Torres Strait Islander flags are distinct flags with different designs and symbolism.","Do not assume every flag question refers only to the Australian National Flag.","NATIONAL · ABORIGINAL · TORRES STRAIT ISLANDER"],
"symbols":["Symbols are compact factual questions, so precision matters.","Golden wattle is the floral emblem; green and gold are national colours; Advance Australia Fair is the anthem.","Do not confuse state emblems with national symbols.","WATTLE · GREEN/GOLD · ANTHEM"],
"democracy":["Parliamentary democracy connects citizen participation to representative government.","Citizens vote for representatives who make decisions in Parliament.","Democracy does not mean every citizen votes directly on every law.","VOTE → REPRESENTATIVES → PARLIAMENT"],
"rule-law":["Rule of law limits both private individuals and government authority.","A religious, family or cultural rule cannot excuse breaking Australian law.","Rule of law is not the same thing as police power; it is the principle that law applies to everyone.","NO ONE ABOVE THE LAW"],
"peaceful-change":["Australian democracy protects disagreement but expects lawful, peaceful methods.","Voting, campaigning and peaceful protest are legitimate; violence and intimidation are not.","Strong disagreement does not create a right to use force.","CHANGE → PEACEFUL + LAWFUL"],
"speech":["Freedom of speech protects lawful expression while coexisting with other laws and rights.","A person may criticise government peacefully.","Freedom of speech is not unlimited permission to threaten or harm others.","SPEAK FREELY → WITHIN LAW"],
"association":["Association protects voluntary participation in lawful groups.","You may join a union, community organisation or political party, or choose not to.","Association does not allow unlawful organisations or forced membership.","JOIN · LEAVE · LAWFUL"],
"religion":["Australia protects belief and non-belief while remaining governed by secular law.","A person may practise a religion or choose no religion.","Religious rules do not replace Australian law.","BELIEF FREE · LAW COMMON"],
"equality-law":["Equal legal status is a foundation for fairness in a diverse society.","People should receive equal protection under Australian law.","Equality under law does not mean every person receives identical outcomes in every situation.","EQUAL RIGHTS UNDER LAW"],
"gender":["Gender equality is explicit, not implied.","Men and women can participate equally in education, work, leadership and public life.","Cultural expectations cannot override equal legal rights.","MEN = WOMEN IN RIGHTS"],
"fair-go":["A fair go is about opportunity and fairness rather than guaranteed results.","Two applicants should have a fair opportunity based on relevant merit rather than gender.","Fair go does not mean everyone must receive the same outcome.","FAIR OPPORTUNITY"],
"responsibilities":["Citizenship carries duties alongside rights and privileges.","An eligible citizen may need to vote, obey law, serve on a jury and defend Australia if required.","A passport is a privilege, not a responsibility.","LAW · VOTE · JURY · DEFEND"],
"privileges":["Citizenship creates specific opportunities not shared in exactly the same way by non-citizens.","Citizens can apply for an Australian passport and may seek election when eligible.","Voting and obeying law belong under responsibilities, not privileges.","PASSPORT · OFFICE · CONSULAR HELP"],
"participation":["Citizenship is framed as active membership of society, not only legal status.","Tax helps fund services; volunteering and community participation strengthen civic life.","Taxation is not an optional donation.","CONTRIBUTE → COMMUNITY"],
"say":["Voting gives eligible citizens a formal say while secret ballot protects personal choice.","Your vote is private even though participation may be compulsory.","Compulsory voting does not mean anyone can force you to vote for a particular candidate.","MUST PARTICIPATE · CHOICE PRIVATE"],
"aec":["The AEC is the independent machinery behind federal electoral participation.","It maintains the electoral roll and administers federal elections and referendums.","The AEC does not decide court cases or make legislation.","AEC → ROLL · ELECTIONS · REFERENDUMS"],
"federation":["Federation explains how separate colonies became one Commonwealth under a federal constitutional system.","Six colonies federated on 1 January 1901.","Federation is not the arrival of Europeans in 1788.","SIX COLONIES → ONE COMMONWEALTH"],
"referendum":["The Constitution has a special change process designed to require broad public support.","A proposed constitutional change is put to eligible voters in a referendum and must meet constitutional majority requirements.","A normal parliamentary Bill cannot by itself rewrite the Constitution.","CONSTITUTION CHANGE → REFERENDUM"],
"powers":["Separating powers by function prevents the words legislative, executive and judicial becoming vocabulary soup.","Parliament makes law; executive government administers it; courts interpret and apply it.","Do not confuse powers with federal/state/local levels.","MAKE · DO · JUDGE"],
"head-state":["Australia combines monarchy with constitutional limits and representative institutions.","The King is Head of State; the Governor-General performs constitutional and ceremonial functions as the King’s representative at Commonwealth level.","The Prime Minister is head of government, not Head of State.","KING → HEAD OF STATE · GG → REPRESENTATIVE"],
"parliament":["The federal Parliament has two houses that participate in national law-making.","The House of Representatives and Senate consider proposed legislation.","Cabinet is not a third house of Parliament.","HOUSE + SENATE"],
"leaders":["Leadership titles reveal the level of government being discussed.","Prime Minister → Commonwealth; Premier → state; Chief Minister → territory; mayor → local.","Premier and Prime Minister are not interchangeable.","PM · PREMIER · CHIEF MINISTER · MAYOR"],
"levels":["Government levels divide responsibilities by scale and jurisdiction.","Defence is federal; public hospitals are mainly state/territory; rubbish collection is local.","Levels are not the same as legislative/executive/judicial powers.","NATIONAL · REGIONAL · LOCAL"],
"parties":["Parliament includes government, Opposition, parties and independents.","A party or coalition with sufficient parliamentary support forms government; others may form the Opposition.","Opposition is a parliamentary role, not opposition to Australian democracy itself.","GOVERNMENT ↔ OPPOSITION"],
"ministers":["Ministers connect political leadership to particular government responsibilities.","A minister may oversee a portfolio such as health; senior ministers form Cabinet.","Cabinet is not the Senate or a court.","PORTFOLIO → MINISTER · SENIOR → CABINET"],
"laws":["Law-making follows an institutional process rather than becoming law when first proposed.","A proposal is a Bill; Parliament considers it; Royal Assent is part of becoming law.","A Bill and an Act/law are not the same stage.","BILL → PARLIAMENT → ROYAL ASSENT → LAW"],
"courts":["Courts exercise judicial power and apply law to disputes and offences.","Judges and magistrates hear cases; juries decide facts in some criminal trials.","Juries do not write laws or run elections.","COURT → JUDGE/MAGISTRATE · SOMETIMES JURY"],
"police":["Police enforce law and protect community safety within legal authority.","AFP handles federal policing functions while state and territory police handle many local policing matters.","Police do not make laws simply because they enforce them.","ENFORCE, NOT LEGISLATE"],
"law-types":["Everyday conduct can engage different areas of law, and violence is not excused by private relationships.","Domestic and family violence can be criminal; road users must obey traffic law.","A family setting does not place violence outside Australian law.","PRIVATE SETTING ≠ OUTSIDE LAW"],
"freedom-dignity":["Values questions often test how principles apply to another person, not merely to yourself.","Respecting another person’s lawful choices protects dignity.","Disagreement does not justify humiliation or violence.","FREEDOM + DIGNITY"],
"values-law":["Values link democracy with common legal obligations.","Peaceful democratic participation operates under the rule of law.","Personal beliefs cannot override Australian law.","DEMOCRACY + RULE OF LAW"],
"values-freedoms":["Australian Values protect pluralism within a common legal framework.","People can speak, associate and believe differently within law.","Freedom does not authorise threats, violence or unlawful discrimination.","FREEDOM WITHIN LAW"],
"values-equality":["Equality links legal rights with fair opportunity.","Gender or background should not remove a person’s equal rights or opportunity.","Equality does not require identical life outcomes.","EQUAL RIGHTS + FAIR OPPORTUNITY"],
"mutual-respect":["A diverse society depends on disagreement without dehumanisation.","Neighbours with different lawful beliefs can respect each other.","Tolerance does not require agreeing with every opinion.","DIFFERENT ≠ DISRESPECTED"],
"community":["Values include contribution, compassion and helping others.","Volunteering after a community emergency reflects mateship and contribution.","Community contribution is broader than paying tax alone.","HELP · VOLUNTEER · CONTRIBUTE"],
"english":["A shared national language supports communication and participation while Australia remains multilingual.","English is Australia’s national language.","National language does not mean other languages are prohibited.","ENGLISH → SHARED NATIONAL LANGUAGE"],
"safety":["Community safety principles apply online as well as offline.","Repeated threatening or humiliating messages intended to harm can be cyber abuse.","Online behaviour is not automatically harmless because it is digital.","DIGITAL HARM IS STILL HARM"],
"loyalty":["Citizenship includes a commitment to Australia and its people alongside legal obligations.","The citizenship pledge expresses loyalty to Australia and its people.","Dual citizenship does not mean Australian law can simply be ignored.","LOYALTY + OBLIGATIONS"]
};
