function orderedDomains(){return curriculumV2.flatMap(p=>p.domains.map(d=>({id:d[0],label:d[1],part:p.id})))}
function studyResume(){const all=orderedDomains(),saved=localStorage.getItem("atest-last-domain"),target=all.find(x=>x.id===saved&&(state.domains[x.id]||0)<3)||all.find(x=>(state.domains[x.id]||0)<3)||all[0];openDomain(target.id)}
function study(){const all=orderedDomains(),done=all.filter(x=>(state.domains[x.id]||0)>=3).length,next=all.find(x=>(state.domains[x.id]||0)<3)||all[0];app.innerHTML=pageHead("STUDY","Your canonical learning path","Move through every testable domain in sequence. A-Test remembers where you left off.")+'<section class="card study-resume"><div><div class="eyebrow">CONTINUE STUDYING</div><h2>'+domainKnowledge[next.id].title+'</h2><p>'+done+' / '+all.length+' domains verified</p></div><button class="btn primary" data-study-resume>Continue →</button></section><div class="curriculum-grid">'+curriculumV2.map(p=>'<article class="card curriculum-part"><div class="eyebrow">PART '+p.part+'</div><h3>'+topicInfo[p.id].icon+' '+p.title+'</h3><p>'+p.domains.filter(d=>(state.domains[d[0]]||0)>=3).length+' / '+p.domains.length+' verified</p><button class="btn" data-domain="'+p.domains.find(d=>(state.domains[d[0]]||0)<3)?.[0]+'">Study next domain →</button></article>').join("")+'</div>'}
function openStudy(id){const g=studyGuide[id];app.innerHTML=pageHead("STUDY GUIDE",topicInfo[id].icon+" "+g.title,g.summary)+'<section class="card study-insight"><div class="eyebrow">CORE INSIGHT</div><p>'+g.insight+'</p></section><div class="lineage">'+g.lineage.map((x,i)=>'<article class="lineage-step"><span>'+(i+1)+'</span><div><div class="eyebrow">LINEAGE '+(i+1)+'</div><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div></article>').join("")+'</div><section class="card study-cue"><div class="eyebrow">EXAM CUE</div><h3>'+g.cue+'</h3></section><div class="actions"><button class="primary" data-topic="'+id+'">Test this topic</button><button data-view="readings">Read long-form material</button><button data-view="study">Study another topic</button></div>'}
function readings(){app.innerHTML=pageHead("READINGS","In-depth learning material","Read for understanding, then retrieve what you learned.")+'<div class="cards">'+Object.entries(readingMaterial).map(([id,r])=>'<article class="card reading-card"><div class="eyebrow">'+topicInfo[id].icon+' '+id.toUpperCase()+'</div><h2>'+r.title+'</h2>'+r.paras.map(p=>'<p>'+p+'</p>').join("")+'<div class="actions"><button class="primary" data-topic="'+id+'">Check understanding</button><button data-lesson="'+id+'">Open lesson</button></div></article>').join("")+'</div>'}
function lesson(id){const t=topicInfo[id],n=conceptNotes[id];app.innerHTML=pageHead("DEEP LESSON",t.icon+" "+t.name,"Understand the idea, then retrieve it.")+'<div class="card" style="margin-bottom:18px"><h3>Why this matters</h3><p>'+n.why+'</p><h3>Example</h3><p>'+n.example+'</p><div class="visual">'+n.hook+'</div></div><div class="cards">'+lessonDetail[id].map(x=>'<article class="card"><h3>'+x[0]+'</h3><p>'+x[1]+'</p></article>').join("")+'</div><div class="actions"><button class="primary" data-topic="'+id+'">Check my recall</button><button data-view="learn">Back to Learning Hub</button></div>'}
function learn(){app.innerHTML=pageHead("LEARNING HUB","Learn the four testable areas","Build understanding first, then lock it in with visualisation and retrieval.")+'<div class="cards">'+Object.entries(topicInfo).map(([id,t])=>'<article class="card"><h3>'+t.icon+' '+t.name+'</h3><ul>'+t.items.map(x=>'<li>'+x+'</li>').join("")+'</ul><div class="actions"><button class="primary" data-lesson="'+id+'">Open lesson</button><button data-topic="'+id+'">Practise topic</button></div></article>').join("")+'</div>'}
function visual(){app.innerHTML=pageHead("VISUAL STORIES","Explore the ideas","Choose a story, tap through each concept, then complete its mini-check.")+'<div class="cards">'+Object.entries(visualStories).map(([id,v])=>'<button class="card visual-story-card" data-story="'+id+'"><div class="story-icon">'+v.icon+'</div><h3>'+v.title+'</h3><p>'+v.nodes.length+' interactive concepts + mini-check</p></button>').join("")+'</div>'}
function openStory(id){visualState={id,seen:[]};drawStory()}
function drawStory(){const v=visualStories[visualState.id];app.innerHTML=pageHead("VISUAL STORY",v.icon+" "+v.title,"Tap each node to reveal the meaning. Complete all nodes to unlock the mini-check.")+'<div class="story-track">'+v.nodes.map((n,i)=>'<button class="story-node '+(visualState.seen.includes(i)?"seen":"")+'" data-story-node="'+i+'"><span>'+(i+1)+'</span><b>'+n[0]+'</b></button>').join("")+'</div><div class="card story-detail" id="story-detail"><p class="hint">Choose a node to explore it.</p></div>'+(visualState.seen.length===v.nodes.length?'<div class="actions"><button class="primary" data-story-check>Unlock mini-check →</button></div>':"")}
function storyNode(i){if(!visualState.seen.includes(i))visualState.seen.push(i);const v=visualStories[visualState.id],n=v.nodes[i];drawStory();document.querySelector("#story-detail").innerHTML='<div class="eyebrow">CONCEPT '+(i+1)+'</div><h2>'+n[0]+'</h2><p class="lead">'+n[1]+'</p>'}
function storyCheck(){const v=visualStories[visualState.id],c=v.check;app.innerHTML=pageHead("MINI-CHECK",v.icon+" "+v.title,"Use retrieval, not recognition.")+'<section class="card quiz"><div class="question">'+c[0]+'</div><div class="choices">'+c[1].map((x,i)=>'<button class="choice" data-story-answer="'+i+'">'+x+'</button>').join("")+'</div><div id="story-feedback"></div></section>'}
function storyAnswer(i){const v=visualStories[visualState.id],c=v.check,ok=i===c[2],st=state.stats[visualState.id]||{c:0,t:0};st.t++;if(ok)st.c++;state.stats[visualState.id]=st;save();document.querySelectorAll("[data-story-answer]").forEach((b,n)=>{b.disabled=true;if(n===c[2])b.classList.add("correct");else if(n===i)b.classList.add("wrong")});document.querySelector("#story-feedback").innerHTML='<div class="feedback"><b class="'+(ok?"good":"bad")+'">'+(ok?"✓ Visual story mastered":"✕ Review the story once more")+'</b><p>'+v.nodes.find(n=>n[0].toLowerCase().includes(c[1][c[2]].toLowerCase().split(" ")[0]))?.[1]+'</p><div class="actions"><button class="primary" data-view="visual">Choose another story</button><button data-story="'+visualState.id+'">Replay story</button></div></div>'}
function map(){app.innerHTML=pageHead("MAP LAB","States, territories & capitals","Explore the pairs, then test yourself with a scored capital challenge.")+'<div class="actions"><button class="primary" data-mapquiz>▶ Capital Challenge</button></div>'+'<div class="maplab"><div class="card">'+places.map((p,i)=>'<button class="statebtn" data-place="'+i+'">'+p[0]+'</button>').join("")+'</div><div class="card" id="place"><h3>Choose a state or territory</h3><p class="hint">Say the capital aloud before revealing it.</p></div></div>'}
function mapQuiz(){const items=shuffle(places.slice());session={mapItems:items,i:0,score:0,mode:"mapquiz"};drawMapQuiz()}
function drawMapQuiz(){const p=session.mapItems[session.i],opts=shuffle([p[1],...shuffle(places.filter(x=>x[1]!==p[1])).slice(0,3).map(x=>x[1])]);app.innerHTML=pageHead("CAPITAL CHALLENGE","What is the capital of "+p[0]+"?","Question "+(session.i+1)+" / "+session.mapItems.length+" · Score "+session.score)+'<section class="card quiz"><div class="choices">'+opts.map(x=>'<button class="choice" data-mapanswer="'+encodeURIComponent(x)+'">'+x+'</button>').join("")+'</div></section>'}
function mapAnswer(ans){const p=session.mapItems[session.i],ok=ans===p[1];if(ok)session.score++;const st=state.stats.people||{c:0,t:0};st.t++;if(ok)st.c++;state.stats.people=st;save();session.i++;if(session.i>=session.mapItems.length){app.innerHTML=pageHead("MAP CHALLENGE COMPLETE",session.score+" / "+session.mapItems.length,"Capital recall now contributes to Australia & its people mastery.")+'<button class="btn primary" data-view="map">Play again</button>';return}drawMapQuiz()}
