function cards(){const now=Date.now(),due=flashcards.map((c,i)=>({i,d:state.reviews[i]||0})).filter(x=>x.d<=now).sort((a,b)=>a.d-b.d);if(due.length&&!flipped)cardIndex=due[0].i;const c=flashcards[cardIndex],known=!!state.known[cardIndex];app.innerHTML=pageHead("FLASHCARDS","Build recall","Think first, reveal second, then rate your recall.")+'<section class="card flash"><div class="eyebrow">'+c[2].toUpperCase()+' · '+(cardIndex+1)+' / '+flashcards.length+'</div><div class="face">'+(flipped?c[1]:c[0])+'</div><p class="hint">'+(flipped?"Answer":"Retrieve it before you tap reveal.")+'</p><div class="actions" style="justify-content:center"><button class="primary" data-flip>'+(flipped?"Show question":"Reveal answer")+'</button>'+(flipped?'<button data-rate="0">× Review again</button><button data-rate="1">✓ I know it</button>':"")+'</div><p class="'+(known?"good":"hint")+'">'+(known?"✓ Marked known":"Not mastered yet")+'</p></section><div class="actions" style="justify-content:center"><button data-prev>← Previous</button><button data-next>Next →</button></div>'}
function evidencePriority(){
 return Object.keys(domainKnowledge).map(function(id){
  const ev=state.domainEvidence[id]||{c:0,t:0},stage=state.domains[id]||0,acc=ev.t?ev.c/ev.t:0;let score=0,reason="";
  if(stage<1){score=100;reason="Not encountered"}else if(stage<3&&ev.t===0){score=90;reason="Needs practice evidence"}else if(stage<3&&ev.t<3){score=80+(3-ev.t)*3;reason="Needs more attempts"}else if(stage<3&&acc<.75){score=85;reason="Accuracy below 75%"}else if(stage<3){score=75;reason="Needs another correct retrieval"}else{score=10;reason="Verified"}
  return {id:id,score:score,reason:reason,ev:ev,stage:stage,part:domainKnowledge[id].part};
 }).sort(function(a,b){return b.score-a.score})
}
function adaptiveEvidence(){const p=evidencePriority().filter(x=>x.stage<3),wanted=p.slice(0,10).map(x=>x.id);let q=questions.filter(x=>wanted.includes(questionDomainMap[x[1]]));q=shuffle(q).slice(0,10);if(!q.length){practice();return}startSession(q,"evidence")}
function adaptiveReinforce(){const misses=Object.keys(state.missed).filter(k=>state.missed[k]>0),weak=Object.keys(topicInfo).sort((a,b)=>pct(a)-pct(b))[0];let q=questions.filter(x=>misses.includes(x[1]));q=q.concat(questions.filter(x=>x[0]===weak&&!q.includes(x)));startSession(shuffle(q).slice(0,10),"adaptive")}
function practice(){const need=evidencePriority().filter(x=>x.stage<3).slice(0,6);const rows=need.map(function(x){return '<div class="queue-row"><span>'+topicInfo[x.part].icon+'</span><div><b>'+domainKnowledge[x.id].title+'</b><small>'+x.reason+' · '+x.ev.c+'/'+x.ev.t+' correct</small></div></div>'}).join("");app.innerHTML=pageHead("PRACTISE","Build the evidence you still need","Adaptive Evidence prioritises unverified domains, insufficient attempts and low accuracy.")+'<section class="card evidence-queue"><div class="eyebrow">YOUR EVIDENCE QUEUE</div><div class="queue-list">'+(rows||'<p class="good">✓ Every domain is verified. Maintain it with mixed practice.</p>')+'</div><div class="actions"><button class="primary" data-evidence>▶ Train my evidence gaps</button><button data-topic="all">Mixed drill</button><button data-view="mistakes">Review mistakes</button></div></section><div class="cards">'+Object.entries(topicInfo).map(([id,t])=>'<button class="card" data-topic="'+id+'" style="text-align:left;cursor:pointer"><h3>'+t.icon+' '+t.name+'</h3><p>'+pct(id)+'% topic accuracy</p></button>').join("")+'</div>'}
function mistakes(){const ks=Object.keys(state.missed).filter(k=>state.missed[k]>0).sort((a,b)=>state.missed[b]-state.missed[a]);if(!ks.length){app.innerHTML=pageHead("MISTAKES","Clean slate ✓","No unresolved mistakes yet. Keep practising to generate useful signals.")+'<button class="btn primary" data-view="practice">Start practice</button>';return}app.innerHTML=pageHead("MISTAKES","Turn errors into assets","The questions below are currently your highest-value review opportunities.")+'<div class="cards">'+ks.map(k=>'<article class="card"><div class="eyebrow">'+state.missed[k]+' MISS'+(state.missed[k]>1?"ES":"")+'</div><h3>'+k+'</h3></article>').join("")+'</div><div class="actions"><button class="primary" data-action="mistakes">Train my mistakes</button></div>'}
function readiness(){const all=curriculumV2.flatMap(p=>p.domains.map(d=>({id:d[0],label:d[1],part:p.id}))),counts={unseen:0,encountered:0,understood:0,building:0,verified:0};all.forEach(x=>{const st=state.domains[x.id]||0,ev=state.domainEvidence[x.id]||{c:0,t:0};if(st>=3)counts.verified++;else if(ev.t>0)counts.building++;else if(st>=2)counts.understood++;else if(st>=1)counts.encountered++;else counts.unseen++});const pri=evidencePriority().filter(x=>x.stage<3).slice(0,8),ms=state.mocks.slice(-3),mockReady=ms.length===3&&ms.every(m=>m.score>=15&&m.values===5),complete=counts.verified===all.length&&mockReady;app.innerHTML=pageHead("PROGRESS","42-domain mastery cockpit","One definition of progress across Curriculum, Study, Practise and Mock Exam.")+'<section class="card progress-hero"><div><div class="eyebrow">VERIFIED COVERAGE</div><h2>'+counts.verified+' / '+all.length+'</h2><div class="progress-bar"><i style="width:'+Math.round(counts.verified/all.length*100)+'%"></i></div><p class="'+(complete?"good":"hint")+'">'+(complete?"✓ Curriculum verified and recent mocks meet both pass gates.":"Keep building evidence. Verification requires repeated retrieval, not a single correct answer.")+'</p></div></section><div class="stage-grid">'+stage("○","Unseen",counts.unseen,"stage-unseen")+stage("◐","Encountered",counts.encountered,"stage-seen")+stage("◆","Understood",counts.understood,"stage-understood")+stage("↻","Building evidence",counts.building,"stage-building")+stage("✓","Verified",counts.verified,"stage-verified")+'</div><div class="curriculum-grid">'+curriculumV2.map(p=>'<article class="card curriculum-part"><div class="eyebrow">PART '+p.part+'</div><h3>'+topicInfo[p.id].icon+' '+p.title+'</h3><div class="mastery-heatmap">'+p.domains.map(d=>{const st=state.domains[d[0]]||0,ev=state.domainEvidence[d[0]]||{t:0};const cls=st>=3?"verified":ev.t?"building":st>=2?"understood":st>=1?"seen":"unseen";return '<button class="heat-cell '+cls+'" data-domain="'+d[0]+'" title="'+d[1]+'">'+(st>=3?"✓":ev.t?"↻":st>=2?"◆":st>=1?"◐":"○")+'<span>'+d[1]+'</span></button>'}).join("")+'</div></article>').join("")+'</div><section class="card next-path"><div class="eyebrow">SHORTEST PATH TO 42 / 42</div><div class="queue-list">'+(pri.length?pri.map((x,i)=>'<div class="queue-row"><span>'+(i+1)+'</span><div><b>'+domainKnowledge[x.id].title+'</b><small>'+x.reason+' · '+x.ev.c+'/'+x.ev.t+' correct</small></div></div>').join(""):'<p class="good">✓ All curriculum domains verified.</p>')+'</div><div class="actions"><button class="primary" data-evidence>Train next gaps</button><button data-view="mock">Take mock exam</button></div></section>'}
function stage(icon,label,n,cls){return '<div class="stage-card '+cls+'"><span>'+icon+'</span><b>'+n+'</b><small>'+label+'</small></div>'}
function games(){const best=Number(localStorage.getItem("atest-quest-best")||0),verified=curriculumAudit().verified;app.innerHTML=pageHead("PLAY","Citizenship Quest","Learn by doing. Clear four missions, protect your lives and build an XP streak.")+'<section class="quest-welcome"><div><div class="eyebrow">YOUR QUEST</div><h2>Journey across Australia’s civic world</h2><p>Every challenge reinforces testable knowledge and feeds your mastery evidence.</p><div class="quest-stats"><span><b>'+best+'</b><small>Best XP</small></span><span><b>'+verified+'/42</b><small>Verified</small></span><span><b>3</b><small>Lives</small></span></div><button class="btn primary" data-quest-start>▶ Begin Citizenship Quest</button></div><div class="quest-badge">🏆</div></section><div class="quest-map">'+questMission(1,"🪪","Citizen Base","Responsibilities vs privileges","rights")+questMission(2,"🗺️","Government Trail","Federal, state/territory and local","government")+questMission(3,"⚖️","Parliament Peak","Legislative, executive and judicial","government")+questMission(4,"🤝","Values Summit","Apply Australian Values to real situations","values")+'</div><section class="card play-tools"><div><div class="eyebrow">QUICK GAMES</div><h3>Want a shorter round?</h3></div><div class="actions"><button data-view="game">⚡ Keyword Forge</button><button data-view="map">◇ Capital Challenge</button><button data-view="cards">▣ Flashcards</button></div></section>'}
function questMission(n,icon,title,desc,part){return '<article class="quest-mission"><div class="mission-pin">'+icon+'</div><div><small>MISSION '+n+'</small><h3>'+title+'</h3><p>'+desc+'</p><span>'+pct(part)+'% topic accuracy</span></div></article>'}
function startQuest(){quest={mission:0,index:0,lives:3,xp:0,streak:0,maxStreak:0};loadMission()}
function loadMission(){const ids=Object.keys(sortGames);if(quest.mission>=ids.length)return winQuest();quest.id=ids[quest.mission];quest.items=shuffle(sortGames[quest.id].items.slice());quest.index=0;drawQuest()}
function drawQuest(){const g=sortGames[quest.id],item=quest.items[quest.index],mult=Math.min(3,1+Math.floor(quest.streak/3));app.innerHTML='<section class="quest-shell"><div class="quest-hud"><div><small>MISSION</small><b>'+(quest.mission+1)+'/4</b></div><div><small>LIVES</small><b class="lives">'+("♥ ".repeat(quest.lives)||"0")+'</b></div><div><small>STREAK</small><b>🔥 '+quest.streak+'</b></div><div><small>MULTIPLIER</small><b>×'+mult+'</b></div><div><small>XP</small><b>'+quest.xp+'</b></div></div><div class="card quest-card"><div class="eyebrow">'+g.title.toUpperCase()+' · '+(quest.index+1)+'/'+quest.items.length+'</div><div class="question">'+item[0]+'</div><div class="choices">'+g.bins.map(x=>'<button class="choice" data-quest-bin="'+encodeURIComponent(x)+'">'+x+'</button>').join("")+'</div><div id="quest-feedback"></div></div></section>'}
function questAnswer(bin){const item=quest.items[quest.index],ok=bin===item[1],mult=Math.min(3,1+Math.floor(quest.streak/3));if(ok){quest.streak++;quest.maxStreak=Math.max(quest.maxStreak,quest.streak);quest.xp+=100*mult}else{quest.lives--;quest.streak=0}const questTopic={citizenship:"rights",levels:"government",powers:"government",valuesort:"values"}[quest.id];const qs=state.stats[questTopic]||{c:0,t:0};qs.t++;if(ok)qs.c++;state.stats[questTopic]=qs;save();document.querySelectorAll("[data-quest-bin]").forEach(x=>{x.disabled=true;const v=decodeURIComponent(x.dataset.questBin);if(v===item[1])x.classList.add("correct");else if(v===bin)x.classList.add("wrong")});document.querySelector("#quest-feedback").innerHTML='<div class="feedback"><b class="'+(ok?"good":"bad")+'">'+(ok?"+"+(100*mult)+" XP":"♥ Life lost")+'</b><p><strong>'+item[0]+'</strong> → '+item[1]+'</p><button class="btn primary" id="quest-next">'+(quest.lives?"Continue":"Results")+'</button></div>';document.querySelector("#quest-next").onclick=()=>{if(!quest.lives)return loseQuest();quest.index++;if(quest.index>=quest.items.length){quest.xp+=250;quest.mission++;return loadMission()}drawQuest()}}
function winQuest(){const best=Math.max(quest.xp,Number(localStorage.getItem("atest-quest-best")||0));localStorage.setItem("atest-quest-best",best);const rank=quest.xp>=5000?"Federation Master":quest.xp>=3500?"Civic Champion":"Citizen Scholar";app.innerHTML=pageHead("QUEST COMPLETE","🏆 "+rank,quest.xp+" XP · Best streak "+quest.maxStreak)+'<section class="card quest-result"><div class="quest-trophy">🏆</div><h2>All missions cleared</h2><div class="actions"><button class="primary" data-quest-start>Play again</button><button data-view="readiness">Readiness</button></div></section>'}
function loseQuest(){const best=Math.max(quest.xp,Number(localStorage.getItem("atest-quest-best")||0));localStorage.setItem("atest-quest-best",best);app.innerHTML=pageHead("QUEST OVER","Recharge and return",quest.xp+" XP · Best streak "+quest.maxStreak)+'<section class="card quest-result"><div class="quest-trophy">🛡️</div><h2>Three lives used</h2><p>Review the missed concepts and come back for the clear.</p><div class="actions"><button class="primary" data-quest-start>Retry quest</button><button data-view="learn">Review lessons</button></div></section>'}
function game(){gameState={score:0,streak:0,round:0,current:null};nextGame()}
function nextGame(){if(gameState.round>=10){app.innerHTML=pageHead("KEYWORD FORGE","Run complete ⚡","You scored "+gameState.score+" / 10.")+'<div class="card"><h3>Best streak: '+gameState.streak+'</h3><p>Run it again to make the language automatic.</p><div class="actions"><button class="primary" data-view="game">Play again</button><button data-view="learn">Review lessons</button></div></div>';return}const correct=keywords[Math.floor(Math.random()*keywords.length)],others=shuffle(keywords.filter(x=>x[0]!==correct[0])).slice(0,3),opts=shuffle([correct,...others]);gameState.current=correct;app.innerHTML=pageHead("KEYWORD FORGE","Match the keyword","Round "+(gameState.round+1)+" / 10 · Score "+gameState.score)+'<section class="card quiz"><div class="question">'+correct[1]+'</div><div class="choices">'+opts.map(x=>'<button class="choice" data-keyword="'+encodeURIComponent(x[0])+'">'+x[0]+'</button>').join("")+'</div><div id="game-feedback"></div></section>'}
function gameAnswer(term){const ok=term===gameState.current[0];if(ok){gameState.score++;gameState.streak++}else gameState.streak=0;gameState.round++;document.querySelectorAll("[data-keyword]").forEach(b=>{b.disabled=true;const t=decodeURIComponent(b.dataset.keyword);if(t===gameState.current[0])b.classList.add("correct");else if(t===term)b.classList.add("wrong")});document.querySelector("#game-feedback").innerHTML='<div class="feedback"><b class="'+(ok?"good":"bad")+'">'+(ok?"✓ Forged":"✕ Reforge")+'</b><p><strong>'+gameState.current[0]+'</strong> → '+gameState.current[1]+'</p><button class="btn primary" id="game-next">Next</button></div>';document.querySelector("#game-next").onclick=nextGame}
function values(){start("values")}
function mock(){if(mockTimer)clearInterval(mockTimer);const values=shuffle(questions.filter(q=>q[0]==="values")),nonValues=shuffle(questions.filter(q=>q[0]!=="values"));const chosen=[],used=new Set();function add(pool,n){for(const q of pool){const dom=questionDomainMap[q[1]]||q[1];if(!used.has(dom)||chosen.length>15){chosen.push(q);used.add(dom);if(--n===0)break}}if(n>0){for(const q of pool){if(!chosen.includes(q)){chosen.push(q);if(--n===0)break}}}}add(nonValues,15);add(values,5);session={q:shuffle(chosen.slice(0,20)),i:0,score:0,mode:"mock",valuesCorrect:0,answers:[],started:Date.now()};mockEnds=Date.now()+45*60*1000;drawMockQuestion();startMockClock()}
function drawMockQuestion(){const q=session.q[session.i];app.innerHTML='<section class="card quiz mock-shell"><div class="mock-top"><div class="eyebrow">MOCK EXAM · QUESTION '+(session.i+1)+' / 20</div><div id="mock-clock" class="mock-clock">45:00</div></div><div class="question">'+q[1]+'</div><div class="choices">'+q[2].map((x,i)=>'<button class="choice" data-mock-answer="'+i+'">'+String.fromCharCode(65+i)+'. '+x+'</button>').join("")+'</div><p class="hint">Answers are locked when selected. Explanations appear after the exam.</p></section>'}
function mockAnswer(i){const q=session.q[session.i],ok=i===q[3],domain=questionDomainMap[q[1]];session.answers.push({q:q,chosen:i,ok:ok,domain:domain});if(ok){session.score++;if(q[0]==="values")session.valuesCorrect++}if(domain){const ev=state.domainEvidence[domain]||{c:0,t:0};ev.t++;if(ok)ev.c++;state.domainEvidence[domain]=ev;const old=state.domains[domain]||0;if(ev.t>=3&&ev.c>=2&&ev.c/ev.t>=.75)state.domains[domain]=Math.max(old,3);else state.domains[domain]=Math.max(old,1)}save();session.i++;if(session.i>=session.q.length)return finishMock();drawMockQuestion()}
function finishMock(){if(mockTimer){clearInterval(mockTimer);mockTimer=null}const pass=session.score>=15&&session.valuesCorrect===5,elapsed=Math.round((Date.now()-session.started)/60000),misses=session.answers.filter(a=>!a.ok);state.mocks.push({score:session.score,values:session.valuesCorrect,pass:pass,date:Date.now(),minutes:elapsed});state.mocks=state.mocks.slice(-10);save();app.innerHTML=pageHead("MOCK EXAM RESULT",pass?"Pass standard met ✓":"Not yet","Pass requires at least 15/20 overall and 5/5 Values.")+'<div class="cards"><div class="card"><div class="eyebrow">OVERALL</div><h2>'+session.score+' / 20</h2></div><div class="card"><div class="eyebrow">VALUES</div><h2>'+session.valuesCorrect+' / 5</h2></div><div class="card"><div class="eyebrow">TIME USED</div><h2>'+elapsed+' min</h2></div><div class="card"><div class="eyebrow">DOMAINS TO RECOVER</div><h2>'+new Set(misses.map(x=>x.domain).filter(Boolean)).size+'</h2></div></div><section class="card mock-review"><h3>Post-exam diagnostics</h3>'+(misses.length?misses.map(a=>'<div class="review-row"><div><b>'+a.q[1]+'</b><p class="bad">Your answer: '+a.q[2][a.chosen]+'</p><p class="good">Correct: '+a.q[2][a.q[3]]+'</p><small>'+a.q[4]+'</small></div>'+(a.domain?'<button class="btn" data-domain="'+a.domain+'">Study '+domainKnowledge[a.domain].title+'</button>':'')+'</div>').join(""):'<p class="good">✓ No incorrect answers. Excellent retrieval.</p>')+'<div class="actions"><button class="primary" data-view="mock">Take another mock</button><button data-evidence>Train evidence gaps</button><button data-view="readiness">View Progress</button></div></section>'}
function startMockClock(){if(mockTimer)clearInterval(mockTimer);mockTimer=setInterval(()=>{if(!session||session.mode!=="mock"){clearInterval(mockTimer);mockTimer=null;return}const left=Math.max(0,mockEnds-Date.now()),el=document.querySelector("#mock-clock");if(el)el.textContent=Math.floor(left/60000)+":"+String(Math.floor((left%60000)/1000)).padStart(2,"0");if(left<=0){clearInterval(mockTimer);mockTimer=null;if(session&&session.mode==="mock")finishMock();else finish()}},1000)}
function start(mode){let q=mode==="all"?questions.slice():questions.filter(x=>x[0]===mode);startSession(shuffle(q),mode)}
function startSession(q,mode){session={q,i:0,score:0,mode,valuesCorrect:0};drawQuestion()}
function drawQuestion(){const q=session.q[session.i];app.innerHTML='<section class="card quiz"><div class="eyebrow">'+(session.mode==="mock"?'MOCK EXAM · <span id="mock-clock">45:00</span>':"REINFORCEMENT")+' · '+(session.i+1)+' / '+session.q.length+'</div><div class="question">'+q[1]+'</div><div class="choices">'+q[2].map((x,i)=>'<button class="choice" data-answer="'+i+'">'+String.fromCharCode(65+i)+'. '+x+'</button>').join("")+'</div><div id="feedback"></div></section>'}
function answer(i){const q=session.q[session.i],ok=i===q[3],domain=questionDomainMap[q[1]];if(ok){session.score++;if(q[0]==="values")session.valuesCorrect++;state.missed[q[1]]=0}else state.missed[q[1]]=(state.missed[q[1]]||0)+1;const s=state.stats[q[0]]||{c:0,t:0};s.t++;if(ok)s.c++;state.stats[q[0]]=s;if(domain){const ev=state.domainEvidence[domain]||{c:0,t:0};ev.t++;if(ok)ev.c++;state.domainEvidence[domain]=ev;const old=state.domains[domain]||0,acc=ev.c/ev.t;if(ev.t>=3&&ev.c>=2&&acc>=.75)state.domains[domain]=Math.max(old,3);else if(ev.t>=1)state.domains[domain]=Math.max(old,1)}save();document.querySelectorAll(".choice").forEach((b,n)=>{b.disabled=true;if(n===q[3])b.classList.add("correct");else if(n===i)b.classList.add("wrong")});document.querySelector("#feedback").innerHTML='<div class="feedback"><b class="'+(ok?"good":"bad")+'">'+(ok?"✓ Correct":"✕ Not yet")+'</b><p>'+q[4]+'</p><button class="btn primary" id="next">'+(session.i===session.q.length-1?"Finish":"Next")+'</button></div>';document.querySelector("#next").onclick=()=>{session.i++;session.i>=session.q.length?finish():drawQuestion()}}
function finish(){if(mockTimer){clearInterval(mockTimer);mockTimer=null}if(session.mode==="mock"){const pass=session.score>=15&&session.valuesCorrect===5;state.mocks.push({score:session.score,values:session.valuesCorrect,pass,date:Date.now()});state.mocks=state.mocks.slice(-10);save();app.innerHTML=pageHead("MOCK EXAM RESULT",pass?"Pass standard met ✓":"Not yet","Pass requires at least 15/20 overall and 5/5 values.")+'<div class="cards"><div class="card"><h3>'+session.score+' / 20</h3><p>Overall score</p></div><div class="card"><h3>'+session.valuesCorrect+' / 5</h3><p>Values score</p></div></div><div class="actions"><button class="primary" data-view="home">Back to dashboard</button><button data-view="mock">Retake</button></div>';return}const p=Math.round(session.score/session.q.length*100);app.innerHTML=pageHead("SESSION COMPLETE",session.score+" / "+session.q.length,p+"% correct")+'<div class="actions"><button class="primary" data-view="practice">Train again</button><button data-view="mistakes">Review mistakes</button></div>'}
function recommended(){const r=nextAction();if(r.topic)start(r.topic);else route(r.view)}
function weakest(){const ids=Object.keys(topicInfo);ids.sort((a,b)=>pct(a)-pct(b));start(ids[0])}
function trainMistakes(){const ks=Object.keys(state.missed).filter(k=>state.missed[k]>0);const q=questions.filter(x=>ks.includes(x[1]));if(q.length)startSession(q,"mistakes");else practice()}
function shuffle(a){return a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1])}
function route(view){document.querySelectorAll(".nav button").forEach(b=>b.classList.toggle("active",b.dataset.view===view));({home:dashboard,syllabus,audit,glossary,learn,readings,study,visual,map,cards,game,games,practice,mistakes,values,mock,readiness}[view]||dashboard)();window.scrollTo({top:0,behavior:"smooth"})}
document.addEventListener("click",e=>{const v=e.target.closest("[data-view]"),t=e.target.closest("[data-topic]"),a=e.target.closest("[data-answer]");if(v)return route(v.dataset.view);if(t)return start(t.dataset.topic);const l=e.target.closest("[data-lesson]");if(l)return lesson(l.dataset.lesson);if(a)return answer(+a.dataset.answer);if(e.target.closest("[data-study-resume]"))return studyResume();const mqa=e.target.closest("[data-mock-answer]");if(mqa)return mockAnswer(+mqa.dataset.mockAnswer);if(e.target.closest("[data-evidence]"))return adaptiveEvidence();const dom=e.target.closest("[data-domain]");if(dom)return openDomain(dom.dataset.domain);const dm=e.target.closest("[data-domain-master]");if(dm){state.domains[dm.dataset.domainMaster]=2;save();return openDomain(dm.dataset.domainMaster)}const stg=e.target.closest("[data-study]");if(stg)return openStudy(stg.dataset.study);const story=e.target.closest("[data-story]");if(story)return openStory(story.dataset.story);const sn=e.target.closest("[data-story-node]");if(sn)return storyNode(+sn.dataset.storyNode);if(e.target.closest("[data-story-check]"))return storyCheck();const sa=e.target.closest("[data-story-answer]");if(sa)return storyAnswer(+sa.dataset.storyAnswer);if(e.target.closest("[data-mapquiz]"))return mapQuiz();const ma=e.target.closest("[data-mapanswer]");if(ma)return mapAnswer(decodeURIComponent(ma.dataset.mapanswer));if(e.target.closest("[data-adaptive]"))return adaptiveReinforce();if(e.target.closest("[data-quest-start]"))return startQuest();const qb=e.target.closest("[data-quest-bin]");if(qb)return questAnswer(decodeURIComponent(qb.dataset.questBin));const sg=e.target.closest("[data-sortgame]");if(sg)return startSort(sg.dataset.sortgame);const bin=e.target.closest("[data-bin]");if(bin)return sortAnswer(decodeURIComponent(bin.dataset.bin));const kw=e.target.closest("[data-keyword]");if(kw)return gameAnswer(decodeURIComponent(kw.dataset.keyword));const p=e.target.closest("[data-place]"),r=e.target.closest("[data-reveal]");if(p)return showPlace(+p.dataset.place);if(r)return revealPlace(+r.dataset.reveal);if(e.target.closest("[data-flip]")){flipped=!flipped;return cards()}if(e.target.closest("[data-next]")){cardIndex=(cardIndex+1)%flashcards.length;flipped=false;return cards()}if(e.target.closest("[data-prev]")){cardIndex=(cardIndex-1+flashcards.length)%flashcards.length;flipped=false;return cards()}const rate=e.target.closest("[data-rate]");if(rate){const yes=rate.dataset.rate==="1";state.known[cardIndex]=yes;state.reviews[cardIndex]=Date.now()+(yes?3*86400000:10*60000);save();cardIndex=(cardIndex+1)%flashcards.length;flipped=false;return cards()}const act=e.target.closest("[data-action]");if(e.target.closest("#next-best"))return recommended();if(act?.dataset.action==="weak")return weakest();if(act?.dataset.action==="mistakes")return trainMistakes()});
route("home");